Schema: public
Name: calc_emp_bonus
Result data type: 
Argument data types: IN p_contract_id numeric, IN p_bonus_rate numeric, OUT p_new_salary numeric
Type: proc
Volatility: volatile
Parallel: unsafe
Owner: enterprisedb
Security: definer
Language: edbspl
Source code:
    -- 변수 선언부 (Oracle 데이터 타입인 VARCHAR2 사용 가능)
    v_emp_name    VARCHAR2(50);
    v_base_salary NUMERIC;
BEGIN
    -- 1. 직원 정보 조회 (암시적 커서)
    SELECT emp_name, base_salary 
    INTO v_emp_name, v_base_salary
    FROM epas_emp_contracts
    WHERE contract_id = p_contract_id;
    -- 2. 새로운 급여 계산
    p_new_salary := v_base_salary + (v_base_salary * p_bonus_rate / 100);
    -- 3. 결과 로그 출력 (Oracle 호환 내장 패키지 사용)
    DBMS_OUTPUT.PUT_LINE('====================================');
    DBMS_OUTPUT.PUT_LINE('직원명: ' || v_emp_name);
    DBMS_OUTPUT.PUT_LINE('기존 급여: ' || v_base_salary);
    DBMS_OUTPUT.PUT_LINE('보너스 적용 급여: ' || p_new_salary);
    DBMS_OUTPUT.PUT_LINE('====================================');
EXCEPTION
    -- 예외 처리부 (Oracle 호환 예외 코드)
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('오류: 사번 ' || p_contract_id || '에 해당하는 직원이 없습니다.');
        p_new_salary := 0;
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('알 수 없는 오류 발생: ' || SQLERRM);
        p_new_salary := -1;
END

Schema: public
Name: fn_decrypt
Result data type: character varying
Argument data types: p_enc_hex character varying, p_key character varying
Type: func
Volatility: volatile
Parallel: unsafe
Owner: enterprisedb
Security: definer
Language: edbspl
Source code:
    v_enc_raw    RAW(32767);
    v_dec_raw    RAW(32767);
    v_key_raw    RAW(32);

    -- [수정] 암호화와 동일하게 4358 사용
    v_algo_type  PLS_INTEGER := 4358;
BEGIN
    IF p_enc_hex IS NULL THEN
        RETURN NULL;
    END IF;
    v_enc_raw := HEXTORAW(p_enc_hex);
    -- [수정] 복호화 키 생성도 동일하게 MD5(2) 사용
    v_key_raw := SYS.DBMS_CRYPTO.HASH(SYS.UTL_RAW.CAST_TO_RAW(p_key), 2);
    v_dec_raw := SYS.DBMS_CRYPTO.DECRYPT(
        src => v_enc_raw,
        typ => v_algo_type,
        key => v_key_raw
    );
    RETURN SYS.UTL_RAW.CAST_TO_VARCHAR2(v_dec_raw);
END

Schema: public
Name: fn_encrypt
Result data type: character varying
Argument data types: p_plain_text character varying, p_key character varying
Type: func
Volatility: volatile
Parallel: unsafe
Owner: enterprisedb
Security: definer
Language: edbspl
Source code:
    v_src_raw    RAW(32767);
    v_key_raw    RAW(32);
    v_enc_raw    RAW(32767);

    -- [수정] 4358 = AES128(6) + CBC(256) + PKCS5(4096)
    v_algo_type  PLS_INTEGER := 4358; 
BEGIN
    IF p_plain_text IS NULL THEN
        RETURN NULL;
    END IF;
    v_src_raw := SYS.UTL_RAW.CAST_TO_RAW(p_plain_text);
    -- [수정] 해시 알고리즘을 '2' (MD5)로 변경
    -- 이유: MD5는 16바이트를 반환하므로 AES-128(16바이트 키)과 완벽하게 매칭됨
    v_key_raw := SYS.DBMS_CRYPTO.HASH(SYS.UTL_RAW.CAST_TO_RAW(p_key), 2);
    v_enc_raw := SYS.DBMS_CRYPTO.ENCRYPT(
        src => v_src_raw,
        typ => v_algo_type,
        key => v_key_raw
    );
    RETURN RAWTOHEX(v_enc_raw);
END

Schema: public
Name: fn_migration_test
Result data type: void
Argument data types: 
Type: func
Volatility: volatile
Parallel: unsafe
Owner: enterprisedb
Security: invoker
Language: plpgsql
Source code:
DECLARE
    v_date DATE := sysdate;
    v_count INT;
BEGIN
    -- 오라클 전용 뷰 (user_tables, dba_objects, v$session) 및 함수 (nvl, decode) 사용
    SELECT nvl(count(*), 0) INTO v_count FROM user_tables;
    IF decode(v_count, 0, 'ZERO', 'MANY') = 'ZERO' THEN
        SELECT count(*) INTO v_count FROM dba_objects;
    END IF;
    PERFORM * FROM v$session;
END;

Schema: sc_crypto
Name: proc_generate_crypto_data
Result data type: 
Argument data types: 
Type: proc
Volatility: volatile
Parallel: unsafe
Owner: enterprisedb
Security: definer
Language: edbspl
Source code:
DECLARE
    v_plain_text    VARCHAR2(200);
    v_plain_raw     RAW(2000);
    v_enc_raw       RAW(2000);
    v_hash_raw      RAW(64);
    v_key_raw       RAW(32);
BEGIN
    FOR i IN 1..10 LOOP
        v_key_raw := DBMS_CRYPTO.RANDOMBYTES(8);

        v_hash_raw := DBMS_CRYPTO.HASH(
            UTL_RAW.CAST_TO_RAW('my_secret_pwd_' || i),
            2
        );

        v_plain_text := '이것은 user_' || i || '의 1급 비밀 메시지입니다.';
        v_plain_raw  := UTL_RAW.CAST_TO_RAW(v_plain_text);

        v_enc_raw := DBMS_CRYPTO.ENCRYPT(
            v_plain_raw,
            4353,
            v_key_raw
        );

        INSERT INTO sc_crypto.user_secure_data (
            username, pwd_hash, encryption_key, secure_message
        ) VALUES (
            'user_' || i, v_hash_raw, v_key_raw, v_enc_raw
        );
    END LOOP;
    COMMIT;
END
